dashboard.definition:
{
  "title": "3 · IoT Fleet Health",
  "description": "Move IoT monitoring from reactive to proactive, shared with the external service partner.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
      }
    },
    "md_003": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "USE CASE 3 OF 9  ·  SPITAL AARWALD  ·  SAMPLE DATA",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "md_004": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# IoT Fleet Health — Reactive to Proactive",
        "fontColor": "#E6EDF3"
      }
    },
    "md_005": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "2,400 connected devices run with a partner. Splunk flags degrading devices days before they fail.",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 15
      }
    },
    "bg_006": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#11161D",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 8
      }
    },
    "md_007": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "WHAT WE HEARD",
        "fontColor": "#6E7681",
        "fontSize": "custom",
        "customFontSize": 11
      }
    },
    "md_008": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "*“IoT Systeme werden zur Zeit überhaupt nicht proaktiv überwacht, zu 99% reaktiv. Man arbeitet hier mit einem externen Dienstleister zusammen.”*",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_009": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_010": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "tags · sensors · pumps · nurse call",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_011"
      },
      "title": "Connected IoT devices"
    },
    "bg_012": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_013": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 1,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": "%",
        "unitPosition": "after",
        "underLabel": "last 24 hours",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_014"
      },
      "title": "Online now",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#D03B3B"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#0CA30C"
          }
        ],
        "majorColorConfig": [
          {
            "to": 95,
            "value": "#D03B3B"
          },
          {
            "from": 95,
            "to": 98,
            "value": "#FAB219"
          },
          {
            "from": 98,
            "value": "#0CA30C"
          }
        ]
      }
    },
    "bg_015": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_016": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "battery · signal · heartbeat",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_017"
      },
      "title": "At risk within 7 days",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 20,
            "value": "#E6EDF3"
          },
          {
            "from": 20,
            "value": "#FAB219"
          }
        ]
      }
    },
    "bg_018": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_019": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": "%",
        "unitPosition": "after",
        "underLabel": "was ~1% before",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_020"
      },
      "title": "Partner tickets opened proactively",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#D03B3B"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#0CA30C"
          }
        ]
      }
    },
    "bg_021": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_022": {
      "type": "splunk.line",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "seriesColors": [
          "#3987E5",
          "#199E70",
          "#D95926",
          "#9085E9"
        ],
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_023"
      },
      "title": "Offline devices by type — last 7 days"
    },
    "bg_024": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_025": {
      "type": "splunk.pie",
      "options": {
        "backgroundColor": "#161B22",
        "showDonutHole": true,
        "labelDisplay": "valuesAndPercentage",
        "legendDisplay": "off",
        "seriesColors": [
          "#199E70",
          "#C98500",
          "#3987E5",
          "#D95926"
        ]
      },
      "dataSources": {
        "primary": "ds_026"
      },
      "title": "Fleet health right now"
    },
    "bg_027": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_028": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "Device": {
            "width": 100
          },
          "Type": {
            "width": 170
          },
          "Location": {
            "width": 170
          },
          "Battery": {
            "width": 70
          },
          "Signal": {
            "width": 80
          },
          "Predicted": {
            "width": 85
          },
          "Partner ticket": {
            "width": 115
          },
          "Risk": {
            "width": 80,
            "rowBackgroundColors": "> table | seriesByName(\"Risk\") | matchValue(c0Bg)",
            "rowColors": "> table | seriesByName(\"Risk\") | matchValue(c0Fg)"
          }
        }
      },
      "dataSources": {
        "primary": "ds_029"
      },
      "title": "Next likely failures — ticket opened before the outage",
      "context": {
        "c0Bg": [
          {
            "match": "High",
            "value": "#3F1D20"
          },
          {
            "match": "Medium",
            "value": "#3A2E12"
          },
          {
            "match": "Low",
            "value": "#1F242C"
          }
        ],
        "c0Fg": [
          {
            "match": "High",
            "value": "#FF8A80"
          },
          {
            "match": "Medium",
            "value": "#E3B341"
          },
          {
            "match": "Low",
            "value": "#9AA4B2"
          }
        ]
      }
    },
    "bg_030": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_031": {
      "type": "splunk.column",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#D95926",
          "#3987E5"
        ],
        "stackMode": "stacked",
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_032"
      },
      "title": "Partner tickets per week"
    },
    "bg_033": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "md_034": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "DATA SOURCES NEEDED IN SPLUNK",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "bg_035": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_036": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Wireless LAN controller",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_037": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_038": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "IoT platform / gateway",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_039": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_040": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "CMDB / asset inventory",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
