  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n29,2329\n28,2335\n27,2338\n26,2338\n25,2342\n24,2347\n23,2349\n22,2354\n21,2356\n20,2355\n19,2362\n18,2361\n17,2370\n16,2370\n15,2372\n14,2377\n13,2377\n12,2380\n11,2387\n10,2388\n9,2392\n8,2397\n7,2398\n6,2400\n5,2403\n4,2408\n3,2412\n2,2410\n1,2413\n0,2420\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,pct\n23,98.22\n22,98.84\n21,98.41\n20,98.11\n19,98.72\n18,98.23\n17,98.87\n16,98.13\n15,98.72\n14,98.76\n13,98.32\n12,98.58\n11,98.84\n10,98.41\n9,98.73\n8,96.54\n7,98.68\n6,98.56\n5,98.87\n4,98.21\n3,98.39\n2,98.13\n1,98.5\n0,98.31\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time pct",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"ago,n\n13,60\n12,56\n11,57\n10,54\n9,53\n8,47\n7,46\n6,45\n5,45\n4,40\n3,39\n2,35\n1,35\n0,33\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time n",
